command:
(async () => {
  if (!game.user.isGM) {
    ui.notifications.warn(game.i18n.localize("EX2E.NotGM"));
    return;
  }
  const existing = game.folders.find(
    f => f.type === "Actor" && f.getFlag("exalted2e", "theCircle")
  );
  if (existing) {
    ui.notifications.info(
      game.i18n.format("EX2E.CircleFolderExists", { name: existing.name })
    );
    return;
  }
  await Folder.create({
    name:  game.i18n.localize("EX2E.TheCircleFolderName"),
    type:  "Actor",
    color: "#d4af37",
    flags: { exalted2e: { theCircle: true } }
  });
  await game.settings.set("exalted2e", "theCircleSeeded", true);
  ui.notifications.info(game.i18n.localize("EX2E.CircleFolderCreated"));
})();
